 14	@Controller('webhooks/evolution')
 15	export class EvolutionWebhookController {
 16	  constructor(
 17	    private readonly incoming: IncomingService,
 18	    private readonly prisma: PrismaService,
 19	    private readonly acceptance: MessageAcceptanceService,
 20	  ) {}
 21	
 22	  @Post()
 23	  @HttpCode(200)
 24	  async receber(@Headers('x-leadshug-webhook-secret') segredo: string, @Body() body: EvolutionEvent) {
 25	    this.exigirSegredo(segredo);
 26	
 27	    const evento = body?.event;
 28	    const instancia = body?.instance;
 29	    if (!evento || !instancia) return { received: true };
 30	
 31	    const identity = await this.prisma.providerResourceIdentity.findUnique({
 32	      where: { provider_externalResourceId: { provider: 'NAO_OFICIAL', externalResourceId: instancia } },
 33	      include: { currentChannel: true },
 34	    });
 35	    const canal = identity?.currentChannel;
 36	    if (!identity || !canal || canal.evolutionInstanceName !== instancia) return { received: true };
 37	    const context = { providerResourceIdentityId: identity.id, buId: identity.buId, channelId: canal.id, generation: canal.generation, pairingEpoch: canal.pairingEpoch, channelOrigin: 'NAO_OFICIAL' as const };
 38	    if (canal.ownNumberVerified && canal.verifiedEpoch === canal.pairingEpoch) {
 39	      await this.acceptance.persistVerifiedDiagnostic(context, evento, { instance: instancia, data: body.data });
 40	    } else {
 41	      const rawState = evento === 'connection.update' ? (body.data as ConnectionData | undefined)?.state : undefined;
 42	      const metadata = ['open', 'connecting', 'close'].includes(rawState ?? '') ? rawState : 'PENDING_IDENTITY';
 43	      await this.acceptance.persistCurrentResourceMetadata(context, evento, { instance: instancia, state: metadata });
 44	    }
 45	
 46	    // Os nomes de evento vêm em minúsculo com ponto no payload ENTREGUE, e em
 47	    // maiúsculo com underscore quando são REGISTRADOS. São strings diferentes
 48	    // para a mesma coisa — o parser do Hub já comparou contra o formato errado
 49	    // uma vez (hub-whatsapp/docs/evolution-api-payloads.md).
 50	    switch (evento) {
 51	      case 'messages.upsert':
 52	        if (!canal.ownNumberVerified || canal.verifiedEpoch !== canal.pairingEpoch) throw new ServiceUnavailableException({ code: 'PENDING_IDENTITY' });
