 67	
 68	  private exigirSegredo(recebido: string): void {
 69	    const esperado = process.env.EVOLUTION_WEBHOOK_SECRET ?? '';
 70	    if (!esperado) throw new ForbiddenException({ error: 'Webhook não configurado.', code: 'ORIGEM_NAO_VERIFICAVEL' });
 71	    const a = Buffer.from(esperado);
 72	    const b = Buffer.from(recebido ?? '');
 73	    if (a.length !== b.length || !timingSafeEqual(a, b)) {
 74	      throw new ForbiddenException({ error: 'Origem não reconhecida.', code: 'ORIGEM_INVALIDA' });
 75	    }
 76	  }
