 78	  private async tratarMensagem(context: { buId: string; channelId: string; providerResourceIdentityId: string; generation: number; pairingEpoch: number }, data: UpsertData | undefined): Promise<void> {
 79	    const jid = data?.key?.remoteJid;
 80	    if (!jid) return;
 81	
 82	    const ehGrupo = jid.endsWith('@g.us');
 83	    if (!ehGrupo && !jid.endsWith('@s.whatsapp.net')) return; // LID identity is ambiguous; never extract digits from @lid.
 84	    if (!data?.key?.id?.trim()) throw new ConflictException({ code: 'EXTERNAL_MESSAGE_ID_REQUIRED' });
 85	    const daGente = Boolean(data?.key?.fromMe);
 86	    const texto = data?.message?.conversation ?? data?.message?.extendedTextMessage?.text ?? '';
 87	
 88	    // `pushName` é o nome de QUEM MANDOU aquela mensagem, não o nome do contato
 89	    // da conversa. Numa mensagem nossa ele é o nome do próprio número — usá-lo
 90	    // aqui é o bug que troca o nome do contato pelo do responsável (corrigido
 91	    // no Hub em 756bd91, e não repetido aqui).
 92	    const nome = !ehGrupo && !daGente ? (data?.pushName ?? null) : null;
 93	
 94	    await this.incoming.registrar({
