112	  private async tratarConexao(context: { channelId: string; providerResourceIdentityId: string; buId: string; generation: number; pairingEpoch: number }, data: ConnectionData | undefined): Promise<void> {
113	    const estado = data?.state;
114	    if (!['open', 'connecting', 'close'].includes(estado ?? '')) return;
115	    await this.prisma.$transaction(async (tx) => {
116	      const rows = await tx.$queryRaw<Array<{ id: string }>>`SELECT id FROM provider_resource_identities WHERE id = ${context.providerResourceIdentityId} AND current_channel_id = ${context.channelId} AND bu_id = ${context.buId} FOR UPDATE`;
117	      if (!rows.length) throw new ConflictException({ code: 'IDENTITY_NOT_CURRENT' });
118	      await tx.$queryRaw`SELECT id FROM business_units WHERE id = ${context.buId} FOR UPDATE`;
119	      await tx.$queryRaw`SELECT id FROM bu_channels WHERE id = ${context.channelId} FOR UPDATE`;
120	      const channel = await tx.buChannel.findFirst({ where: { id: context.channelId, buId: context.buId, generation: context.generation, pairingEpoch: context.pairingEpoch }, select: { ownNumberVerified: true, verifiedEpoch: true, receiptVerifiedAt: true, currentAttemptId: true } });
121	      if (!channel) throw new ConflictException({ code: 'CHANNEL_GENERATION_STALE' });
122	      const ready = estado === 'open' && channel.ownNumberVerified && channel.verifiedEpoch === context.pairingEpoch && Boolean(channel.receiptVerifiedAt);
123	      const changed = await tx.buChannel.updateMany({
124	        where: { id: context.channelId, buId: context.buId, generation: context.generation, pairingEpoch: context.pairingEpoch },
125	        data: { providerConnectionState: estado === 'open' ? 'CONNECTED' : estado === 'connecting' ? 'CONNECTING' : 'DISCONNECTED', status: ready ? 'CONECTADO' : estado === 'close' ? 'DESCONECTADO' : 'CONECTANDO', ...(ready ? { connectedAt: new Date() } : { connectedAt: null }) },
126	      });
127	      if (!changed.count) throw new ConflictException({ code: 'CHANNEL_GENERATION_STALE' });
128	      if (ready && channel.currentAttemptId) {
129	        const converged = await tx.channelRegistrationAttempt.updateMany({ where: { id: channel.currentAttemptId, generation: context.generation, pairingEpoch: context.pairingEpoch, state: { in: ['PENDING_NUMBER', 'PENDING_RECEIPT'] } }, data: { state: 'CONNECTED', stage: 'RECEIPT_VERIFIED', version: { increment: 1 } } });
130	        if (!converged.count) throw new ConflictException({ code: 'ATTEMPT_STALE' });
131	      }
132	    });
133	  }
