 73	      where: { active: true, bot: { status: 'ATIVO', mantenedoraId: bu.mantenedoraId }, OR: [{ buId: null }, { buId }] },
 74	      include: { bot: true }, orderBy: { createdAt: 'asc' },
 75	    });
