104	      }
105	      const accepted = await this.acceptance.accept({
106	        providerResourceIdentityId: scoped.providerResourceIdentityId, channelId: scoped.channelId, generation: scoped.generation,
107	        pairingEpoch: scoped.pairingEpoch, buId, channelOrigin: scoped.provider, externalMessageId: externalId,
108	        contact: contato, contactType: 'PESSOA', conversationId, direction: 'OUT', messageType: 'TEXTO', content: saida,
109	        authorName: 'Typebot', senderResult: true,
110	      });
111	      if (accepted.creationWinner) this.realtime.publicarNaBu(buId, { tipo: 'mensagem', conversaId: conversationId, contato, direcao: 'OUT', canal: scoped.provider, naoLidas: accepted.conversation.unreadCount });
112	    }
