117	function textoDaRespostaTypebot(mensagem: unknown): string | null {
118	  if (!mensagem || typeof mensagem !== 'object') return null;
119	  const m = mensagem as { type?: string; content?: { richText?: unknown; text?: string } };
120	  if (m.type !== 'text') return null;
121	  if (typeof m.content?.text === 'string') return m.content.text.trim() || null;
122	  const juntar = (v: unknown): string => Array.isArray(v) ? v.map(juntar).join('') : v && typeof v === 'object' ? juntar((v as { children?: unknown }).children) : typeof v === 'string' ? v : '';
123	  const texto = juntar(m.content?.richText).trim();
124	  return texto || null;
125	}
